#include <stdio.h>

int max_subarray(const int a[], int n) {
    int best = a[0], current = a[0];
    for (int i = 1; i < n; i++) {
        int extend = current + a[i];
        current = extend > a[i] ? extend : a[i];
        if (current > best) best = current;
    }
    return best;
}

int main() {
    int a[] = {-4, -1, -8};
    printf("%d\n", max_subarray(a, 3));
    return 0;
}
